import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o,af as t}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Yuanbao glossary","description":"Yuanbao, Hunyuan, and CodeBuddy are not the same product.","frontmatter":{"title":"Yuanbao glossary","description":"Yuanbao, Hunyuan, and CodeBuddy are not the same product.","domain":"product","tags":["chat"],"role":"explanation"},"headers":[],"relativePath":"products/yuanbao/yuanbao-glossary.md","filePath":"products/yuanbao/yuanbao-glossary.md","lastUpdated":1787107158000}'),s={name:"products/yuanbao/yuanbao-glossary.md"};function r(i,a,d,u,l,p){return o(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="yuanbao-glossary" tabindex="-1">Yuanbao glossary <a class="header-anchor" href="#yuanbao-glossary" aria-label="Permalink to &quot;Yuanbao glossary&quot;">​</a></h1><p>No how-to. This page only keeps the word “Yuanbao” consistent on this site.</p><h2 id="concept-map" tabindex="-1">Concept map <a class="header-anchor" href="#concept-map" aria-label="Permalink to &quot;Concept map&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tencent</span></span>
<span class="line"><span>├── Yuanbao (assistant product, this directory)</span></span>
<span class="line"><span>│   └── Yuanbao Pai (in-app public beta)</span></span>
<span class="line"><span>├── Hunyuan (model / research brand, #77)</span></span>
<span class="line"><span>│   ├── Hy3 (the model name on today&#39;s home page)</span></span>
<span class="line"><span>│   └── Hy AI Studio (Hunyuan footer)</span></span>
<span class="line"><span>├── CodeBuddy (coding assistant, #78)</span></span>
<span class="line"><span>├── WorkBuddy (office workbench, footer)</span></span>
<span class="line"><span>└── ima (knowledge steward, footer)</span></span></code></pre></div><h2 id="yuanbao" tabindex="-1">Yuanbao <a class="header-anchor" href="#yuanbao" aria-label="Permalink to &quot;Yuanbao&quot;">​</a></h2><p><strong>What it is:</strong> Tencent&#39;s consumer all-in-one AI assistant. English name Yuanbao. Door: <a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a>.</p><p><strong>Why it has a page:</strong> it is the personal chat product. It is not the model site and not the coding assistant.</p><p><strong>What it is not:</strong> Hunyuan itself, CodeBuddy, or a CLI.</p><h2 id="hunyuan-hy3" tabindex="-1">Hunyuan / Hy3 <a class="header-anchor" href="#hunyuan-hy3" aria-label="Permalink to &quot;Hunyuan / Hy3&quot;">​</a></h2><p><strong>What it is:</strong> Tencent&#39;s model and research brand. Site: <a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a>. Home says Yuanbao is connected to the latest Hunyuan Hy3 model.</p><p><strong>Versus Yuanbao:</strong> Hunyuan ships models; Yuanbao is one consumer surface. APIs and open weights belong on the Hunyuan handbook (#77).</p><p>Play&#39;s about-text still mentions Hunyuan T1 and DeepSeek R1. That store sentence coexists with home&#39;s Hy3 copy. Trust the list in the client.</p><h2 id="yuanbao-pai" tabindex="-1">Yuanbao Pai <a class="header-anchor" href="#yuanbao-pai" aria-label="Permalink to &quot;Yuanbao Pai&quot;">​</a></h2><p><strong>What it is:</strong> a Yuanbao feature in App Store / Play / Software Center copy, including a public beta that mentions raising lobsters.</p><p><strong>What it is not:</strong> a second downloadable app, and not WorkBuddy.</p><h2 id="codebuddy" tabindex="-1">CodeBuddy <a class="header-anchor" href="#codebuddy" aria-label="Permalink to &quot;CodeBuddy&quot;">​</a></h2><p><strong>What it is:</strong> Tencent Cloud coding assistant. <a href="https://www.codebuddy.cn/" target="_blank" rel="noreferrer">codebuddy.cn</a>. Site issue #78.</p><p><strong>Versus Yuanbao “AI coding”:</strong> Yuanbao&#39;s official wording is running Python / C++ in the thread with no deploy. CodeBuddy is the coding-tool product. This directory stops at this row.</p><h2 id="workbuddy" tabindex="-1">WorkBuddy <a class="header-anchor" href="#workbuddy" aria-label="Permalink to &quot;WorkBuddy&quot;">​</a></h2><p><strong>What it is:</strong> a Hunyuan home-footer product. The site calls it Tencent&#39;s all-scenario AI office workbench (<a href="https://www.workbuddy.cn/" target="_blank" rel="noreferrer">workbuddy.cn</a>).</p><p><strong>What it is not:</strong> a nickname for Yuanbao desktop.</p><h2 id="ima" tabindex="-1">ima <a class="header-anchor" href="#ima" aria-label="Permalink to &quot;ima&quot;">​</a></h2><p><strong>What it is:</strong> a Hunyuan home-footer product. Official line: an AI knowledge steward built on a knowledge base (<a href="https://ima.qq.com/" target="_blank" rel="noreferrer">ima.qq.com</a>).</p><p><strong>What it is not:</strong> a “knowledge-base mode” inside Yuanbao.</p><h2 id="hy-ai-studio" tabindex="-1">Hy AI Studio <a class="header-anchor" href="#hy-ai-studio" aria-label="Permalink to &quot;Hy AI Studio&quot;">​</a></h2><p><strong>What it is:</strong> a footer item on Hunyuan <code>/solutions</code>, listed with Yuanbao and WorkBuddy. It is a model playground on the Hunyuan site, not a Yuanbao tab.</p><h2 id="delivery-shapes-words-from-the-agreement" tabindex="-1">Delivery shapes (words from the agreement) <a class="header-anchor" href="#delivery-shapes-words-from-the-agreement" aria-label="Permalink to &quot;Delivery shapes (words from the agreement)&quot;">​</a></h2><p>The user agreement lists web, PC client, mini program, browser plugin, and future shapes. The first two have public doors. The last two had no standalone official install page on 2026-08-19 — keep the names, do not write install steps.</p><h2 id="do-not-write-these-as-product-names" tabindex="-1">Do not write these as product names <a class="header-anchor" href="#do-not-write-these-as-product-names" aria-label="Permalink to &quot;Do not write these as product names&quot;">​</a></h2><ul><li>“Yuanbao CLI”, “Yuanbao Code”, “Yuanbao IDE plugin” — no official page uses them.</li><li>Calling <code>hunyuan.tencent.com/bot/chat</code> “Hunyuan chat” — it canonicalizes to Yuanbao.</li><li>Treating store-review quotas, prices, or default models as specs.</li></ul>`,30)])])}const g=e(s,[["render",r]]);export{m as __pageData,g as default};
